Geographic search implementation:
```javascript
const { Client } = require('@googlemaps/google-maps-services-js');
const mapsClient = new Client({});

async function findSuppliersInRadius(constructionSite, radius) {
  // Get construction site coordinates
  const siteCoordinates = await getConstructionSiteCoordinates(constructionSite);

  // Query database for suppliers within radius
  const suppliers = await db.query(`
    SELECT id, nome, cnpj, whatsapp, coordenadas, categoria
    FROM fornecedores
    WHERE ST_DWithin(
      ST_SetSRID(ST_Point($1, $2), 4326)::geography,
      coordenadas::geography,
      $3
    )
  `, [siteCoordinates.lng, siteCoordinates.lat, radius]);

  // Calculate distance and estimated delivery time for each supplier
  const suppliersWithDistance = await Promise.all(suppliers.map(async (supplier) => {
    const distanceMatrix = await mapsClient.distancematrix({
      params: {
        origins: [{ lat: siteCoordinates.lat, lng: siteCoordinates.lng }],
        destinations: [{ lat: supplier.coordenadas.x, lng: supplier.coordenadas.y }],
        mode: 'driving',
        key: process.env.GOOGLE_MAPS_API_KEY
      }
    });

    const distance = distanceMatrix.data.rows[0].elements[0].distance.value;
    const duration = distanceMatrix.data.rows[0].elements[0].duration.value;

    return {
      ...supplier,
      distance,
      estimatedDeliveryTime: duration
    };
  }));

  return suppliersWithDistance;
}
```

