PIX integration example:
```javascript
const axios = require('axios');

async function generatePixPayment(invoice) {
  try {
    // Call bank API to generate PIX code
    const response = await axios.post(
      process.env.PIX_API_URL,
      {
        value: invoice.total,
        key: process.env.PIX_KEY,
        description: `Payment for invoice ${invoice.id}`,
        expiresIn: 3600 // 1 hour
      },
      {
        headers: {
          'Authorization': `Bearer ${process.env.PIX_API_TOKEN}`,
          'Content-Type': 'application/json'
        }
      }
    );

    // Store PIX information
    await db.query(`
      INSERT INTO pagamentos (pedido_id, pix_code, pix_expiration, valor, status)
      VALUES ($1, $2, $3, $4, $5)
    `, [
      invoice.pedido_id,
      response.data.pixCode,
      new Date(Date.now() + 3600000), // Now + 1 hour
      invoice.total,
      'pending'
    ]);

    return response.data;
  } catch (error) {
    console.error('Error generating PIX payment:', error);
    throw new Error('Failed to generate PIX payment');
  }
}

async function verifyPayment(paymentId) {
  // Get payment details
  const payment = await db.query('SELECT * FROM pagamentos WHERE id = $1', [paymentId]);
  if (!payment.rows.length) throw new Error('Payment not found');

  // Check with bank API
  const response = await axios.get(
    `${process.env.PIX_API_URL}/status/${payment.rows[0].pix_code}`,
    {
      headers: {
        'Authorization': `Bearer ${process.env.PIX_API_TOKEN}`
      }
    }
  );

  if (response.data.status === 'paid') {
    // Update payment status
    await db.query(
      'UPDATE pagamentos SET status = $1, paid_at = $2 WHERE id = $3',
      ['completed', new Date(), paymentId]
    );

    // Trigger reconciliation
    await reconcilePayment(paymentId);

    return true;
  }

  return false;
}
```

